// self:   http://shadertoy.com/view/l3VfRz
// parent: http://shadertoy.com/view/sdd3R4
// parent: http://shadertoy.com/view/mdtyzN

#define rot(a)    mat2(cos(a + vec4(0, 11, 33, 0)))             // spin

void mainImage(out vec4 O, vec2 U)
{    
    float t = 9.,                                               // tile multiplier
          k = 2., d, a, b, r, ir, s = .123,                     // thanks @dray  // .125
          R0 = 20., R1 = 10.;                                   // large, small radii

    vec3  R = iResolution,
          D = normalize(vec3(U + U, -3.5 * R.y) - R),           // ray direction
          q, p = 90. / R,                                       // march point along ray 
          M = vec3(8,4,0) / 1e2 * cos(iTime + vec3(0, 11, 0));

    for (O = vec4(0); O.x < 1. && t > .01; O += .01)
        q = p,
        q.yz *= rot(.5 + 6. * M.y),                             // rotations
        q.xz *= rot(2. - 6. * M.x),
        t = min(9., length(vec2(d=length(q.xz)-R0,q.y)) - R1),
        p += t * D;                                             // step        

    O = O.x > 1. ? vec4(0.) : exp(-3. / 2. * O);                // luminance (depth + pseudo-shading )
    a = atan(q.z, q.x), b = atan(q.y, d);
    r = R1 / R0, ir = sqrt(1. - r * r);                         // antiderivative of 1/circonf(b) 
    b = 2. / ir * atan((r - 1.) / ir * tan(b / 2.));            // conformal mapping for square cells
    vec2 Q = vec2(2. * a, b);
    O *= (1. - length((mod(Q + s, s + s) - s)                   // blob at grid center
      * inverse(transpose(mat2(dFdx(Q),dFdy(Q))))) * 150./R.y); // compensate distortion with Jacobian (precise)
    O *= exp2(-length(fwidth(Q)));                              // fade silhouette glitches
}
